sys_script_include.script:
var AgendaUtils = Class.create();
AgendaUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    checkDuplicateDate: function() {
        var date = this.getParameter('sysparm_date');
        var course = this.getParameter('sysparm_course');

        // Converter de DD/MM/YYYY para YYYY-MM-DD Necessário para rodar
        if (date.indexOf('/') > -1) {
            var parts = date.split('/');
            date = parts[2] + '-' + parts[1] + '-' + parts[0];
        }

        var gr = new GlideRecord("x_1795292_learni_0_agenda");
        gr.addQuery('course_date', date);
        gr.addQuery('title_course', course);
        gr.query();

        if (gr.next()) {
            return 'true';
        }

        return 'false';
    }
});
